-- Seed the catalogue and services from the previous hard-coded data (skipped if already present).
-- Existing orders: prices used to be entered before GST at invoicing; convert them to GST-inclusive
-- item prices on the order, and track payment separately from fulfilment.
UPDATE "order_items" SET "unit_price_paise" = round(coalesce("unit_price_paise", 0) * 1.18), "gst_rate_bp" = 1800 WHERE "gst_rate_bp" IS NULL;--> statement-breakpoint
UPDATE "orders" o SET
  "items_total_paise" = coalesce((SELECT sum(i."unit_price_paise" * i."quantity") FROM "order_items" i WHERE i."order_id" = o."id"), 0),
  "shipping_paise" = coalesce((SELECT v."shipping_paise" FROM "invoices" v WHERE v."order_id" = o."id"), 0);--> statement-breakpoint
UPDATE "orders" SET "total_paise" = "items_total_paise" + "shipping_paise";--> statement-breakpoint
UPDATE "orders" SET "payment_status" = 'paid', "paid_at" = "updated_at" WHERE "status" = 'paid';--> statement-breakpoint
UPDATE "orders" SET "status" = 'placed' WHERE "status" IN ('invoiced', 'paid');--> statement-breakpoint
-- Invoices are now issued only after payment, as a PDF; old pre-payment invoices are removed.
DELETE FROM "invoices";
